import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type SharedContentInfographicProps = Record<string, any>;

const getPartialPath = (
  x0: number, y0: number, 
  x1: number, y1: number, 
  x2: number, y2: number, 
  x3: number, y3: number, 
  t: number
) => {
  const L = (a: number, b: number, t: number) => a + (b - a) * t;
  if (t <= 0) return { d: "", tipX: x0, tipY: y0, angle: 0 };
  if (t >= 1) return { d: `M ${x0} ${y0} C ${x1} ${y1}, ${x2} ${y2}, ${x3} ${y3}`, tipX: x3, tipY: y3, angle: 0 };
  
  const ax = L(x0, x1, t), ay = L(y0, y1, t);
  const bx = L(x1, x2, t), by = L(y1, y2, t);
  const cx = L(x2, x3, t), cy = L(y2, y3, t);
  
  const dx = L(ax, bx, t), dy = L(ay, by, t);
  const ex = L(bx, cx, t), ey = L(by, cy, t);
  
  const tipX = L(dx, ex, t), tipY = L(dy, ey, t);
  
  const angle = Math.atan2(tipY - dy, tipX - dx) * (180 / Math.PI);
  
  return {
    d: `M ${x0} ${y0} C ${ax} ${ay}, ${dx} ${dy}, ${tipX} ${tipY}`,
    tipX,
    tipY,
    angle
  };
};

const SharedContentInfographic: React.FC<SharedContentInfographicProps> = ({
  backgroundColor = "#0A1128",
  transparentBackground = false,
  durationInSeconds = 8,
  themeColor = "#0096FF",
  titlePart1 = "SHARED",
  titlePart2 = "AD CONTENT",
  masterTitle = "MASTER COPY",
  plumbers = [
    { name: "Bob's Plumbing", team: "Bob's Team", iconColor: "#3B82F6" },
    { name: "Mike's Plumbing", team: "Mike's Team", iconColor: "#22C55E" },
    { name: "Joe's Plumbing", team: "Joe's Team", iconColor: "#EF4444" },
  ],
  masterItems = [
    { label: "15 Headlines", number: "15", color: "#3B82F6" },
    { label: "4 Descriptions", number: "4", color: "#EAB308" },
    { label: "Display Paths", number: "", color: "#22C55E" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const introEnd = 30;
  const masterCardsStart = 30;
  const masterCardsStagger = 15;
  const streamStarts = [75, 90, 105];
  const streamDuration = 45;

  // Layout Coordinates
  const rightPanelX = 1150 * s;
  const rightPanelY = 250 * s;
  const rightPanelWidth = 550 * s;
  const rightPanelHeight = 650 * s;

  const leftCardX = 150 * s;
  const leftCardWidth = 480 * s;
  
  const yCentersRight = [440 * s, 580 * s, 720 * s];
  const yCentersLeft = [340 * s, 580 * s, 820 * s];

  const curveStartX = rightPanelX;
  const curveEndX = leftCardX + leftCardWidth;
  const curveControlX1 = (curveStartX - 250 * s);
  const curveControlX2 = (curveEndX + 250 * s);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* Title */}
      <div
        style={{
          position: "absolute",
          top: 100 * s,
          right: 170 * s,
          width: rightPanelWidth,
          textAlign: "center",
          fontSize: 48 * s,
          fontWeight: 800,
          lineHeight: 1.2,
          opacity: interpolate(frame, [0, introEnd], [0, 1], { extrapolateRight: "clamp" }),
          transform: `translateY(${interpolate(frame, [0, introEnd], [20 * s, 0], { extrapolateRight: "clamp" })}px)`,
          transition: "none",
        }}
      >
        <span style={{ color: "#FFFFFF" }}>{titlePart1}</span>
        <br />
        <span style={{ color: themeColor }}>{titlePart2}</span>
      </div>

      {/* Connectors (SVG Layer) */}
      <svg 
        style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", overflow: "visible", transition: "none" }}
      >
        {streamStarts.map((startFrame, i) => {
          const t = interpolate(frame, [startFrame, startFrame + streamDuration], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
          const { d, tipX, tipY } = getPartialPath(
            curveStartX, yCentersRight[i],
            curveControlX1, yCentersRight[i],
            curveControlX2, yCentersLeft[i],
            curveEndX, yCentersLeft[i],
            t
          );

          const fullPath = `M ${curveStartX} ${yCentersRight[i]} C ${curveControlX1} ${yCentersRight[i]}, ${curveControlX2} ${yCentersLeft[i]}, ${curveEndX} ${yCentersLeft[i]}`;

          // Master copy overall opacity fades in first
          const baseOpacity = interpolate(frame, [0, introEnd], [0, 0.2], { extrapolateRight: "clamp" });

          return (
            <g key={`path-${i}`}>
              {/* Base faint path */}
              <path
                d={fullPath}
                fill="none"
                stroke={themeColor}
                strokeWidth={4 * s}
                strokeOpacity={baseOpacity}
                style={{ transition: "none" }}
              />
              
              {/* Animated solid data stream */}
              {t > 0 && (
                <>
                  <path
                    d={d}
                    fill="none"
                    stroke={themeColor}
                    strokeWidth={6 * s}
                    strokeLinecap="round"
                    style={{ 
                      transition: "none",
                      filter: `drop-shadow(0 0 ${10 * s}px ${themeColor})`
                    }}
                  />
                  {/* Tip Rider */}
                  <circle
                    cx={tipX}
                    cy={tipY}
                    r={8 * s}
                    fill="#FFFFFF"
                    style={{
                      transition: "none",
                      filter: `drop-shadow(0 0 ${15 * s}px ${themeColor})`,
                      opacity: t < 1 ? 1 : 0 // hide exactly when it hits
                    }}
                  />
                  <circle
                    cx={tipX}
                    cy={tipY}
                    r={4 * s}
                    fill={themeColor}
                    style={{
                      transition: "none",
                      opacity: t < 1 ? 1 : 0
                    }}
                  />
                </>
              )}
            </g>
          );
        })}
      </svg>

      {/* Left Plumber Cards */}
      {plumbers.map((plumber, i) => {
        const startFrame = streamStarts[i] + streamDuration; // activates when stream hits
        const isActive = frame >= startFrame;
        
        const cardSpring = spring({
          frame: frame - startFrame,
          fps,
          config: { damping: 12, stiffness: 90 }
        });

        const scale = isActive ? interpolate(cardSpring, [0, 1], [0.95, 1.02]) : 0.95;
        const opacity = interpolate(frame, [0, introEnd], [0, 0.6], { extrapolateRight: "clamp" }) + (isActive ? interpolate(cardSpring, [0, 1], [0, 0.4]) : 0);
        const glowOpacity = isActive ? interpolate(cardSpring, [0, 1], [0, 0.6]) : 0;
        const bgBrightness = isActive ? interpolate(cardSpring, [0, 1], [0.8, 1]) : 0.8;

        return (
          <div
            key={`plumber-${i}`}
            style={{
              position: "absolute",
              left: leftCardX,
              top: yCentersLeft[i] - (180 * s) / 2,
              width: leftCardWidth,
              height: 180 * s,
              backgroundColor: "#FFFFFF",
              borderRadius: 20 * s,
              display: "flex",
              alignItems: "center",
              padding: `0 ${30 * s}px`,
              opacity,
              transform: `scale(${scale})`,
              filter: `brightness(${bgBrightness})`,
              boxShadow: `0 0 ${40 * s}px ${glowOpacity > 0 ? themeColor : 'transparent'}`,
              transition: "none",
            }}
          >
            {/* Plumber Icon Circle */}
            <div style={{
              width: 90 * s,
              height: 90 * s,
              borderRadius: "50%",
              backgroundColor: "#F3F4F6",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              marginRight: 30 * s,
              border: `2px solid ${isActive ? plumber.iconColor : 'transparent'}`,
              transition: "none"
            }}>
              <svg width={40 * s} height={40 * s} viewBox="0 0 24 24" fill="none" stroke={plumber.iconColor} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" style={{ transition: "none" }}>
                {i === 0 && <path d="M12 2v8M8 10h8M10 14h4M12 14v6M9 20h6M5 6a3 3 0 0 1 3-3h8a3 3 0 0 1 3 3v2a3 3 0 0 1-3 3H8a3 3 0 0 1-3-3V6z" />}
                {i === 1 && <path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z" />}
                {i === 2 && <path d="M12 2v10M7 12c0-3 10-3 10 0v2H7v-2zM9 14v2M15 14v2M7 16h10" />}
              </svg>
            </div>
            
            {/* Plumber Text */}
            <div style={{ display: "flex", flexDirection: "column", gap: 10 * s, transition: "none" }}>
              <div style={{ fontSize: 32 * s, fontWeight: 700, color: "#0F172A", transition: "none" }}>
                {plumber.name}
              </div>
              <div style={{ fontSize: 24 * s, color: "#64748B", display: "flex", alignItems: "center", gap: 8 * s, transition: "none" }}>
                <svg width={20 * s} height={20 * s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} style={{ transition: "none" }}>
                  <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
                  <circle cx="9" cy="7" r="4" />
                  <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
                  <path d="M16 3.13a4 4 0 0 1 0 7.75" />
                </svg>
                {plumber.team}
              </div>
            </div>
          </div>
        );
      })}

      {/* Right Master Copy Panel */}
      <div
        style={{
          position: "absolute",
          top: rightPanelY,
          left: rightPanelX,
          width: rightPanelWidth,
          height: rightPanelHeight,
          backgroundColor: "rgba(10, 20, 50, 0.4)",
          backdropFilter: "blur(10px)",
          borderRadius: 24 * s,
          border: `2px solid ${themeColor}`,
          boxShadow: `0 0 ${40 * s}px rgba(0, 150, 255, 0.3)`,
          opacity: interpolate(frame, [0, introEnd], [0, 1], { extrapolateRight: "clamp" }),
          display: "flex",
          flexDirection: "column",
          padding: 40 * s,
          transition: "none",
        }}
      >
        {/* Panel Header */}
        <div style={{ display: "flex", alignItems: "center", gap: 20 * s, marginBottom: 40 * s, transition: "none" }}>
          <svg width={50 * s} height={50 * s} viewBox="0 0 24 24" fill="none" stroke={themeColor} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" style={{ transition: "none" }}>
            <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
            <polyline points="14 2 14 8 20 8" />
            <line x1="16" y1="13" x2="8" y2="13" />
            <line x1="16" y1="17" x2="8" y2="17" />
            <polyline points="10 9 9 9 8 9" />
          </svg>
          <div style={{ fontSize: 36 * s, fontWeight: 700, color: "#FFFFFF", letterSpacing: 1 * s, transition: "none" }}>
            {masterTitle}
          </div>
        </div>

        {/* Master Copy Items */}
        <div style={{ display: "flex", flexDirection: "column", gap: 20 * s, flex: 1, justifyContent: "center", transition: "none" }}>
          {masterItems.map((item, i) => {
            const itemStart = masterCardsStart + (i * masterCardsStagger);
            const itemSpring = spring({ frame: frame - itemStart, fps, config: { damping: 14 } });
            
            const itemOpacity = interpolate(frame, [itemStart, itemStart + 15], [0, 1], { extrapolateRight: "clamp" });
            const borderOpacity = interpolate(itemSpring, [0, 1], [0.2, 0.8]);
            const bgLightness = interpolate(itemSpring, [0, 1], [0, 0.1]);

            return (
              <div
                key={`master-item-${i}`}
                style={{
                  height: 120 * s,
                  borderRadius: 16 * s,
                  border: `2px solid rgba(255, 255, 255, ${borderOpacity})`,
                  backgroundColor: `rgba(255, 255, 255, ${bgLightness})`,
                  display: "flex",
                  alignItems: "center",
                  padding: `0 ${30 * s}px`,
                  gap: 24 * s,
                  opacity: itemOpacity,
                  transform: `translateY(${interpolate(itemSpring, [0, 1], [20 * s, 0])}px)`,
                  transition: "none",
                }}
              >
                {/* Item Icon */}
                <div style={{
                  width: 60 * s,
                  height: 60 * s,
                  borderRadius: 12 * s,
                  border: `2px solid ${item.color}`,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  flexDirection: "column",
                  gap: 4 * s,
                  transition: "none",
                }}>
                  {item.number ? (
                    <span style={{ color: item.color, fontSize: 28 * s, fontWeight: 800, transition: "none" }}>{item.number}</span>
                  ) : (
                    <svg width={30 * s} height={30 * s} viewBox="0 0 24 24" fill="none" stroke={item.color} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" style={{ transition: "none" }}>
                      <rect x="3" y="3" width="18" height="18" rx="2" ry="2" />
                      <line x1="9" y1="3" x2="9" y2="21" />
                      <line x1="9" y1="12" x2="21" y2="12" />
                    </svg>
                  )}
                  {item.number && <div style={{ width: 24 * s, height: 3 * s, backgroundColor: item.color, borderRadius: 2 * s, transition: "none" }} />}
                </div>

                {/* Item Text & Lines */}
                <div style={{ display: "flex", flexDirection: "column", gap: 12 * s, flex: 1, transition: "none" }}>
                  <div style={{ fontSize: 26 * s, fontWeight: 600, color: "#FFFFFF", transition: "none" }}>
                    {item.label}
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", gap: 6 * s, transition: "none" }}>
                    <div style={{ height: 4 * s, width: "80%", backgroundColor: "rgba(255, 255, 255, 0.2)", borderRadius: 2 * s, transition: "none" }} />
                    <div style={{ height: 4 * s, width: "60%", backgroundColor: "rgba(255, 255, 255, 0.1)", borderRadius: 2 * s, transition: "none" }} />
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default SharedContentInfographic;